1	// contractlab —— 可热更新的本地接口场景服务
2	//
3	// 运行环境：Node.js 24（内置 TypeScript 类型擦除，可直接 `node app.ts`），
4	// 无任何外部运行依赖。
5	//
6	// 行为约定（详见 README.md）：
7	// - 业务接口由“方法 + 绝对路径”唯一标识，查询串不参与匹配，不支持路径模板；
8	// - 请求被完整接收后，才按当前配置匹配接口并同步“预留”响应序列的下一项，
9	//   序列耗尽后持续返回末项；预留之后客户端断开，仍计为一次消费；
10	// - POST /__contractlab/reload 重新读取同一配置文件：新配置全部有效时才
11	//   原子替换全部接口、重置全部序列并递增版本号；失败时现状不变；
12	// - 在途请求持有预留时的旧响应快照（状态码/响应头/正文/延迟/版本），
13	//   完成时不会推进新序列；
14	// - POST 接口可附加可选的 requestBody 正文结构规则：请求完整接收后先校验
15	//   媒体类型与 JSON 结构，不符时返回 400 差异报告，不发送场景响应、不消费序列；
16	//   校验通过才按“完整接收”顺序预留响应项。
17	// - 管理入口 GET /__contractlab/requests 查询本次进程内的请求记录（一致快照、
18	//   不推进序列），POST /__contractlab/requests/clear 清空记录；记录只存在内存中，
19	//   管理范围（/__contractlab 本身及 /__contractlab/ 前缀）的请求一律不记录。
20	// - compare 子命令：离线比较旧、新两份场景文件，判断沿用旧接口约定的客户端
21	//   是否仍能调用新版；报告写 stdout，不启动监听、不修改文件。
22	// - import 子命令：读取本地 OpenAPI 3.0 JSON 与现有场景配置，按“方法 + 字面
23	//   路径”选择文档操作，仅用操作 requestBody 转换出的正文规则替换各接口的
24	//   requestBody（保留接口顺序与 responses），新场景 JSON 写 stdout。
25	// - verify 子命令：离线批量请求校验。读取 GET /__contractlab/requests 的完整
26	//   JSON 快照与一份场景配置，按输入顺序保留原编号逐条重新判定（仅依据记录中的
27	//   原始请求重新计算，不信任原版本、匹配/校验结论、计划响应与发送状态）；
28	//   报告写 stdout，不监听、不发送请求、不修改文件。
29	// - replay 子命令：本机请求重放与响应差异报告。读取同一份请求记录快照，
30	//   按输入顺序把每条记录的原始请求逐条重放到 127.0.0.1 的指定端口
31	//   （每条只尝试一次、不跟随重定向、每条有覆盖完整收发的总超时），
32	//   仅比较实际响应的状态码与正文原始字节和记录中的计划响应；
33	//   报告写 stdout，不监听、不修改文件。
34	
35	import http from 'node:http';
36	import { readFile } from 'node:fs/promises';
37	import path from 'node:path';
38	
39	const APP_NAME = 'contractlab';
40	
41	// 管理入口（保留前缀，业务接口不得使用）
42	const ADMIN_PREFIX = '/__contractlab/';
43	const ADMIN_BASE = '/__contractlab';
44	const HEALTH_PATH = '/__contractlab/health';
45	const RELOAD_PATH = '/__contractlab/reload';
46	const REQUESTS_PATH = '/__contractlab/requests';
47	const REQUESTS_CLEAR_PATH = '/__contractlab/requests/clear';
48	
49	// 每个业务响应都携带当前配置版本
50	const VERSION_HEADER = 'X-Contractlab-Version';
51	
52	// 请求体上限（本机工具的防误操作保护，超出直接 413，不触碰任何序列）
53	const MAX_BODY_BYTES = 100 * 1024 * 1024;
54	
55	// 由服务器管理、业务配置不得覆盖的“传输头”（大小写不敏感）
56	const BLOCKED_HEADERS = new Set([
57	  'connection',
58	  'keep-alive',
59	  'content-length',
60	  'transfer-encoding',
61	]);
62	
63	// RFC 7230 token：合法的 HTTP 头名称字符
64	const HEADER_NAME_RE = /^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/;
65	
66	type HttpMethod = 'GET' | 'POST';
67	
68	// ---------------------------------------------------------------------------
69	// 请求正文结构规则（endpoints[].requestBody，仅 POST）
70	// ---------------------------------------------------------------------------
71	//
72	// 规则格式（JSON 对象，未知字段一律拒绝）：
73	//   { "type": "object", "fields": { "<名>": <字段规则>, ... }, "additionalProperties": false }
74	//   { "type": "array", "items": <规则> }
75	//   { "type": "string" | "number" | "integer" | "boolean" | "null" }
76	// 字段规则 = 任意规则 + 可选 "required": true（缺省为可缺省）；
77	// object 的 fields / additionalProperties 可省略（默认无字段声明、拒绝未声明字段）；
78	// array 必须声明 items。
79	
80	type ScalarKind = 'string' | 'number' | 'integer' | 'boolean' | 'null';
81	
82	type BodyRule =
83	  | {
84	      readonly kind: 'object';
85	      readonly fields: ReadonlyMap<string, FieldRule>;
86	      readonly additionalProperties: boolean;
87	    }
88	  | { readonly kind: 'array'; readonly items: BodyRule }
89	  | { readonly kind: ScalarKind };
90	
91	interface FieldRule {
92	  readonly rule: BodyRule;
93	  readonly required: boolean;
94	}
95	
96	interface ResponseSpec {
97	  readonly status: number;
98	  readonly headers: { readonly [name: string]: string };
99	  readonly body: string;
100	  readonly delay: number;
101	}
102	
103	interface EndpointSpec {
104	  readonly method: HttpMethod;
105	  readonly path: string;
106	  readonly responses: readonly ResponseSpec[];
107	  readonly bodyRule: BodyRule | undefined;
108	}
109	
110	interface LiveEndpoint {
111	  readonly key: string;
112	  readonly responses: readonly ResponseSpec[];
113	  readonly bodyRule: BodyRule | undefined;
114	  // 下一个待预留位置；到达末项后停在末项（持续复用）
115	  cursor: number;
116	}
117	
118	interface LiveState {
119	  readonly version: number;
120	  readonly endpoints: ReadonlyMap<string, LiveEndpoint>;
121	}
122	
123	interface ReloadResult {
124	  ok: boolean;
125	  version: number;
126	  error?: string;
127	}
128	
129	class ConfigError extends Error {
130	  constructor(message: string) {
131	    super(message);
132	    this.name = 'ConfigError';
133	  }
134	}
135	
136	// ---------------------------------------------------------------------------
137	// 配置校验
138	// ---------------------------------------------------------------------------
139	
140	function isPlainObject(value: unknown): value is Record<string, unknown> {
141	  return typeof value === 'object' && value !== null && !Array.isArray(value);
142	}
143	
144	function validatePath(p: string, where: string): void {
145	  if (p.length === 0 || p[0] !== '/') {
146	    throw new ConfigError(`${where}.path 必须是以 "/" 开头的绝对路径，收到 "${p}"`);
147	  }
148	  if (p.length > 4096) {
149	    throw new ConfigError(`${where}.path 过长（最多 4096 字符）`);
150	  }
151	  for (const ch of p) {
152	    const code = ch.charCodeAt(0);
153	    if (ch === '?' || ch === '#' || ch === '{' || ch === '}') {
154	      throw new ConfigError(
155	        `${where}.path "${p}" 含有非法字符 "${ch}"：查询串不参与匹配，且不支持路径模板`,
156	      );
157	    }
158	    if (code <= 0x1f || code === 0x7f || code === 0x20) {
159	      throw new ConfigError(`${where}.path "${p}" 不得包含空白或控制字符`);
160	    }
161	  }
162	}
163	
164	function validateResponse(raw: unknown, where: string): ResponseSpec {
165	  if (!isPlainObject(raw)) {
166	    throw new ConfigError(`${where} 必须是对象`);
167	  }
168	  for (const key of Object.keys(raw)) {
169	    if (key !== 'status' && key !== 'headers' && key !== 'body' && key !== 'delay') {
170	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
171	    }
172	  }
173	
174	  const { status, headers, body, delay } = raw;
175	
176	  if (!Number.isInteger(status) || status < 200 || status > 599) {
177	    throw new ConfigError(`${where}.status 必须是 200 至 599 之间的整数，收到 ${JSON.stringify(status)}`);
178	  }
179	
180	  if (!isPlainObject(headers)) {
181	    throw new ConfigError(`${where}.headers 必须是字符串键值对象`);
182	  }
183	  // 无原型对象：名为 "__proto__" 的头也按自有字段保留，不被原型 setter 吞掉
184	  const cleanHeaders: { [name: string]: string } = Object.create(null);
185	  const seenNames = new Set<string>();
186	  for (const [name, value] of Object.entries(headers)) {
187	    const whereHeader = `${where}.headers["${name}"]`;
188	    if (!HEADER_NAME_RE.test(name)) {
189	      throw new ConfigError(`${whereHeader} 不是合法的 HTTP 响应头名称`);
190	    }
191	    const lower = name.toLowerCase();
192	    if (BLOCKED_HEADERS.has(lower)) {
193	      throw new ConfigError(`${whereHeader} 属于服务器管理的传输头，不允许在配置中设置`);
194	    }
195	    if (seenNames.has(lower)) {
196	      throw new ConfigError(`${whereHeader} 与同序列内另一个响应头仅大小写不同，视为重复`);
197	    }
198	    if (typeof value !== 'string') {
199	      throw new ConfigError(`${whereHeader} 的值必须是字符串`);
200	    }
201	    for (let i = 0; i < value.length; i += 1) {
202	      const code = value.charCodeAt(i);
203	      // 允许水平制表符(0x09)；拒绝换行及其余控制字符；
204	      // Node 的 HTTP 头值只支持 Latin-1（0x80-0xFF），更高码位发送时会抛错
205	      if ((code <= 0x1f && code !== 0x09) || code === 0x7f || code > 0xff) {
206	        throw new ConfigError(
207	          `${whereHeader} 的值不得包含换行或其他控制字符，且只能使用 Latin-1 字符`,
208	        );
209	      }
210	    }
211	    seenNames.add(lower);
212	    cleanHeaders[name] = value;
213	  }
214	
215	  if (typeof body !== 'string') {
216	    throw new ConfigError(`${where}.body 必须是文本字符串`);
217	  }
218	  if ((status === 204 || status === 304) && body !== '') {
219	    throw new ConfigError(`${where}.body 状态码为 ${status} 时正文必须为空字符串`);
220	  }
221	
222	  if (!Number.isInteger(delay) || delay < 0 || delay > 60000) {
223	    throw new ConfigError(`${where}.delay 必须是 0 至 60000 之间的整数毫秒数，收到 ${JSON.stringify(delay)}`);
224	  }
225	
226	  return { status, headers: cleanHeaders, body, delay };
227	}
228	
229	const SCALAR_KINDS: ReadonlySet<string> = new Set([
230	  'string',
231	  'number',
232	  'integer',
233	  'boolean',
234	  'null',
235	]);
236	
237	function validateBodyRule(raw: unknown, where: string): BodyRule {
238	  if (!isPlainObject(raw)) {
239	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
240	  }
241	
242	  const type = raw.type;
243	  const allowed = new Set(['type']);
244	  if (type === 'object') {
245	    allowed.add('fields');
246	    allowed.add('additionalProperties');
247	  } else if (type === 'array') {
248	    allowed.add('items');
249	  } else if (!SCALAR_KINDS.has(type as string)) {
250	    throw new ConfigError(
251	      `${where}.type 必须是 "object" | "array" | "string" | "number" | "integer" | "boolean" | "null"，收到 ${JSON.stringify(type)}`,
252	    );
253	  }
254	  for (const key of Object.keys(raw)) {
255	    if (!allowed.has(key)) {
256	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
257	    }
258	  }
259	
260	  if (type === 'object') {
261	    const fieldsRaw = raw.fields;
262	    const fields = new Map<string, FieldRule>();
263	    if (fieldsRaw !== undefined) {
264	      if (!isPlainObject(fieldsRaw)) {
265	        throw new ConfigError(`${where}.fields 必须是对象（字段名 → 字段规则）`);
266	      }
267	      for (const [name, fieldRaw] of Object.entries(fieldsRaw)) {
268	        fields.set(name, validateFieldRule(fieldRaw, `${where}.fields[${JSON.stringify(name)}]`));
269	      }
270	    }
271	    const additional = raw.additionalProperties;
272	    if (additional !== undefined && typeof additional !== 'boolean') {
273	      throw new ConfigError(`${where}.additionalProperties 必须是布尔值`);
274	    }
275	    // 未声明字段默认拒绝
276	    return { kind: 'object', fields, additionalProperties: additional === true };
277	  }
278	
279	  if (type === 'array') {
280	    if (raw.items === undefined) {
281	      throw new ConfigError(`${where}.items 数组规则必须声明元素规则`);
282	    }
283	    return { kind: 'array', items: validateBodyRule(raw.items, `${where}.items`) };
284	  }
285	
286	  return { kind: type as ScalarKind };
287	}
288	
289	// 字段规则 = 任意规则 + 可选 "required"（仅允许出现在 object 的 fields 条目中）
290	function validateFieldRule(raw: unknown, where: string): FieldRule {
291	  if (!isPlainObject(raw)) {
292	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
293	  }
294	  let required = false;
295	  // 无原型对象：未知规则键 "__proto__" 必须作为自有字段保留下来，
296	  // 交由 validateBodyRule 拒绝；普通对象字面量会在复制时被原型 setter 吞掉
297	  const rest: Record<string, unknown> = Object.create(null);
298	  for (const [key, value] of Object.entries(raw)) {
299	    if (key === 'required') {
300	      if (typeof value !== 'boolean') {
301	        throw new ConfigError(`${where}.required 必须是布尔值`);
302	      }
303	      required = value;
304	    } else {
305	      rest[key] = value;
306	    }
307	  }
308	  return { rule: validateBodyRule(rest, where), required };
309	}
310	
311	function validateEndpoint(
312	  raw: unknown,
313	  index: number,
314	  seen: Set<string>,
315	): EndpointSpec {
316	  const where = `endpoints[${index}]`;
317	  if (!isPlainObject(raw)) {
318	    throw new ConfigError(`${where} 必须是对象`);
319	  }
320	  for (const key of Object.keys(raw)) {
321	    if (key !== 'method' && key !== 'path' && key !== 'responses' && key !== 'requestBody') {
322	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
323	    }
324	  }
325	
326	  const { method, path: routePath, responses, requestBody } = raw;
327	
328	  if (method !== 'GET' && method !== 'POST') {
329	    throw new ConfigError(`${where}.method 必须是 "GET" 或 "POST"，收到 ${JSON.stringify(method)}`);
330	  }
331	
332	  if (typeof routePath !== 'string') {
333	    throw new ConfigError(`${where}.path 必须是字符串`);
334	  }
335	  validatePath(routePath, where);
336	  if (routePath === '/__contractlab' || routePath.startsWith(ADMIN_PREFIX)) {
337	    throw new ConfigError(
338	      `${where}.path "${routePath}" 与管理入口冲突：前缀 "${ADMIN_PREFIX}" 为管理接口保留`,
339	    );
340	  }
341	
342	  const key = `${method} ${routePath}`;
343	  if (seen.has(key)) {
344	    throw new ConfigError(`${where} 与其他接口重复（方法 + 路径必须唯一）：${key}`);
345	  }
346	  seen.add(key);
347	
348	  if (!Array.isArray(responses) || responses.length === 0) {
349	    throw new ConfigError(`${where}.responses 必须是非空数组`);
350	  }
351	  const cleanResponses = responses.map((item, j) =>
352	    validateResponse(item, `${where}.responses[${j}]`),
353	  );
354	
355	  let bodyRule: BodyRule | undefined;
356	  if (requestBody !== undefined) {
357	    if (method !== 'POST') {
358	      throw new ConfigError(`${where}.requestBody 仅允许在 POST 接口上声明（GET 接口不允许携带此规则）`);
359	    }
360	    bodyRule = validateBodyRule(requestBody, `${where}.requestBody`);
361	  }
362	
363	  return { method, path: routePath, responses: cleanResponses, bodyRule };
364	}
365	
366	function validateConfig(raw: unknown): EndpointSpec[] {
367	  if (!isPlainObject(raw)) {
368	    throw new ConfigError('配置顶层必须是 JSON 对象');
369	  }
370	  for (const key of Object.keys(raw)) {
371	    if (key !== 'endpoints') {
372	      throw new ConfigError(`未知顶层字段 "${key}"，仅允许 "endpoints"`);
373	    }
374	  }
375	  const list = raw.endpoints;
376	  if (!Array.isArray(list) || list.length === 0) {
377	    throw new ConfigError('endpoints 必须是至少包含一个接口的数组');
378	  }
379	  const seen = new Set<string>();
380	  return list.map((ep, i) => validateEndpoint(ep, i, seen));
381	}
382	
383	// ---------------------------------------------------------------------------
384	// 运行时状态：配置快照 + 每接口独立序列
385	// ---------------------------------------------------------------------------
386	
387	function buildState(version: number, specs: readonly EndpointSpec[]): LiveState {
388	  const endpoints = new Map<string, LiveEndpoint>();
389	  for (const spec of specs) {
390	    endpoints.set(`${spec.method} ${spec.path}`, {
391	      key: `${spec.method} ${spec.path}`,
392	      responses: spec.responses,
393	      bodyRule: spec.bodyRule,
394	      cursor: 0,
395	    });
396	  }
397	  return { version, endpoints };
398	}
399	
400	// 同步预留下一项；同一事件循环内按“完整接收”事件的先后串行调用，天然保序。
401	// 末项之后持续返回末项，不跳项、不复用未到位置的项。
402	// 返回本次消费位置（0 起）与该项；末项复用时位置停在 length-1。
403	function reserveNext(endpoint: LiveEndpoint): { position: number; item: ResponseSpec } {
404	  const last = endpoint.responses.length - 1;
405	  const position = endpoint.cursor < last ? endpoint.cursor : last;
406	  if (endpoint.cursor < last) {
407	    endpoint.cursor += 1;
408	  }
409	  return { position, item: endpoint.responses[position] };
410	}
411	
412	// ---------------------------------------------------------------------------
413	// 进程内请求记录
414	// ---------------------------------------------------------------------------
415	//
416	// 仅记录管理范围之外、完整接收且未超过正文上限的请求（场景响应、400、404）。
417	// 未收完整即断开或超出上限不创建记录、不消费序列。
418	// 编号按“完整接收”顺序在进程内单调递增，与接口消费位置是两回事；
419	// 清空与成功/失败重载都保留编号序列，编号不复用。记录只存在内存中，不写文件。
420	
421	// 写出生命周期（仅指服务器侧写出，不表示客户端已收到）：
422	//   pending     —— 已完整接收、计划响应待发送（延迟期间即可查到）
423	//   sent        —— 服务器已完成响应写出；此后连接正常关闭不再改变状态
424	//   interrupted —— 写出完成前连接断开或写入/发送失败
425	type DeliveryStatus = 'pending' | 'sent' | 'interrupted';
426	
427	// 计划响应：场景响应为 'scene'，400/404 等框架响应为 'framework'
428	interface PlannedResponseSnapshot {
429	  readonly kind: 'scene' | 'framework';
430	  readonly status: number;
431	  // 应用层响应头：配置头/框架头 + 服务器填写的准确版本头，不含传输层自动头
432	  readonly headers: { readonly [name: string]: string };
433	  // 配置/框架给出的响应正文文本（不含 HTTP 层按 Content-Length 等补出的字节）
434	  readonly body: string;
435	}
436	
437	interface RequestRecord {
438	  readonly id: number;
439	  readonly receivedAt: string;
440	  readonly request: {
441	    readonly method: string;
442	    // 含查询串的原始请求目标
443	    readonly target: string;
444	    readonly path: string;
445	    // 原始请求头：按在线顺序成对保留，名称大小写与重复头均不折叠
446	    readonly rawHeaders: readonly string[];
447	    readonly bodyBytes: number;
448	    // 正文原始字节的无损表示：合法 UTF-8 时以文本给出，否则以 base64 给出
449	    readonly body: { readonly encoding: 'utf-8' | 'base64'; readonly content: string };
450	  };
451	  // 完整接收那一刻选用的配置版本；在途请求的结论不随之后的 reload 改变
452	  configVersion: number;
453	  // matched=false：未匹配（404），不消费任何序列
454	  matched: boolean;
455	  endpoint: string | null;
456	  // null 表示未做正文校验（GET/未声明规则）；true=通过，false=拒绝并返回 400
457	  bodyValidationPassed: boolean | null;
458	  // 400 时实际返回的差异报告（与响应正文中的 JSON 同一份数据）
459	  bodyRejection: BodyReport | null;
460	  // 场景请求在序列中的消费位置（0 起）；400/404 没有消费位置，记为 null
461	  sequencePosition: number | null;
462	  sequenceLength: number | null;
463	  plannedResponse: PlannedResponseSnapshot | null;
464	  delivery: DeliveryStatus;
465	}
466	
467	// 已清空记录的投递回调落到空集合上：不取消响应，旧请求之后完成也不得重新出现。
468	class RequestLog {
469	  private records: RequestRecord[] = [];
470	  // 仍可能被投递事件更新的记录 id 集合（清空后旧 id 不在其中）
471	  private readonly live = new Map<number, RequestRecord>();
472	  private nextId = 1;
473	
474	  create(entry: {
475	    method: string;
476	    target: string;
477	    path: string;
478	    rawHeaders: readonly string[];
479	    body: Buffer;
480	    configVersion: number;
481	  }): RequestRecord {
482	    const id = this.nextId;
483	    this.nextId += 1;
484	    const record: RequestRecord = {
485	      id,
486	      receivedAt: new Date().toISOString(),
487	      request: {
488	        method: entry.method,
489	        target: entry.target,
490	        path: entry.path,
491	        rawHeaders: entry.rawHeaders,
492	        bodyBytes: entry.body.byteLength,
493	        body: encodeBodyLosslessly(entry.body),
494	      },
495	      configVersion: entry.configVersion,
496	      matched: false,
497	      endpoint: null,
498	      bodyValidationPassed: null,
499	      bodyRejection: null,
500	      sequencePosition: null,
501	      sequenceLength: null,
502	      plannedResponse: null,
503	      delivery: 'pending',
504	    };
505	    this.records.push(record);
506	    this.live.set(id, record);
507	    return record;
508	  }
509	
510	  // 写出完成；对已清空（不再存活）的记录是 no-op
511	  markDelivered(id: number, status: DeliveryStatus): void {
512	    const record = this.live.get(id);
513	    if (!record) {
514	      return;
515	    }
516	    // 一旦完成写出即为终态：之后的连接正常关闭不得回退为 interrupted
517	    if (record.delivery === 'sent') {
518	      return;
519	    }
520	    record.delivery = status;
521	  }
522	
523	  // 调用时一致快照：拷贝当前存活记录，不推进任何序列
524	  snapshot(): readonly RequestRecord[] {
525	    return [...this.records];
526	  }
527	
528	  // 清空一次移除当时全部记录（含待发送项）；不取消响应、不改配置/版本/序列。
529	  // 清空前已完整接收的请求随后完成或失败都不再出现。
530	  clear(): number {
531	    const removed = this.records.length;
532	    this.records = [];
533	    this.live.clear();
534	    return removed;
535	  }
536	}
