551	// ---------------------------------------------------------------------------
552	// 请求正文校验：媒体类型 → UTF-8 JSON 解析 → 结构比对
553	// ---------------------------------------------------------------------------
554	
555	interface StructureProblem {
556	  readonly pointer: string;
557	  readonly expected: string;
558	  readonly actual: string;
559	}
560	
561	interface BodyReport {
562	  readonly error: 'invalid_request_body';
563	  readonly stage: 'parse' | 'structure';
564	  readonly message: string;
565	  readonly problems: readonly StructureProblem[];
566	}
567	
568	function parseFailure(message: string): BodyReport {
569	  return { error: 'invalid_request_body', stage: 'parse', message, problems: [] };
570	}
571	
572	function jsonTypeOf(value: unknown): string {
573	  if (value === null) {
574	    return 'null';
575	  }
576	  if (Array.isArray(value)) {
577	    return 'array';
578	  }
579	  return typeof value;
580	}
581	
582	// RFC 6901 JSON Pointer 段转义：~ -> ~0，/ -> ~1
583	function escapePointerSegment(segment: string): string {
584	  return segment.replace(/~/g, '~0').replace(/\//g, '~1');
585	}
586	
587	// 结构比对：父节点类型不符时只报告该节点，不再深入制造子节点错误；
588	// 字段缺失（hasOwnProperty 为假）与合法的 JSON null 分开判断。
589	function checkRule(
590	  rule: BodyRule,
591	  value: unknown,
592	  pointer: string,
593	  problems: StructureProblem[],
594	): void {
595	  switch (rule.kind) {
596	    case 'string':
597	    case 'boolean':
598	      if (typeof value !== rule.kind) {
599	        problems.push({ pointer, expected: rule.kind, actual: jsonTypeOf(value) });
600	      }
601	      return;
602	    case 'null':
603	      if (value !== null) {
604	        problems.push({ pointer, expected: 'null', actual: jsonTypeOf(value) });
605	      }
606	      return;
607	    case 'number':
608	      if (typeof value !== 'number' || !Number.isFinite(value)) {
609	        problems.push({ pointer, expected: 'number', actual: jsonTypeOf(value) });
610	      }
611	      return;
612	    case 'integer':
613	      if (!Number.isInteger(value)) {
614	        problems.push({ pointer, expected: 'integer', actual: jsonTypeOf(value) });
615	      }
616	      return;
617	    case 'array': {
618	      if (!Array.isArray(value)) {
619	        problems.push({ pointer, expected: 'array', actual: jsonTypeOf(value) });
620	        return;
621	      }
622	      for (let i = 0; i < value.length; i += 1) {
623	        checkRule(rule.items, value[i], `${pointer}/${i}`, problems);
624	      }
625	      return;
626	    }
627	    case 'object': {
628	      if (!isPlainObject(value)) {
629	        problems.push({ pointer, expected: 'object', actual: jsonTypeOf(value) });
630	        return;
631	      }
632	      for (const [name, field] of rule.fields) {
633	        const childPointer = `${pointer}/${escapePointerSegment(name)}`;
634	        if (!Object.prototype.hasOwnProperty.call(value, name)) {
635	          if (field.required) {
636	            problems.push({
637	              pointer: childPointer,
638	              expected: `${field.rule.kind}（必填字段）`,
639	              actual: 'missing',
640	            });
641	          }
642	        } else {
643	          checkRule(field.rule, value[name], childPointer, problems);
644	        }
645	      }
646	      if (!rule.additionalProperties) {
647	        for (const key of Object.keys(value)) {
648	          if (!rule.fields.has(key)) {
649	            problems.push({
650	              pointer: `${pointer}/${escapePointerSegment(key)}`,
651	              expected: '未声明的字段（不允许）',
652	              actual: jsonTypeOf(value[key]),
653	            });
654	          }
655	        }
656	      }
657	      return;
658	    }
659	  }
660	}
661	
662	// 返回 null 表示校验通过；否则为可直接序列化的 400 差异报告。
663	// contentType 为在线顺序第一项 Content-Type 头值（在线：Node 对重复
664	// content-type 只保留首项；离线 verify：取 rawHeaders 中首个同名头）。
665	// 正文解码与 JSON 解析不重写原文：BOM 与空白按 UTF-8 解码的默认规则处理，
666	// 在线与离线对同一组字节给出同一结论。
667	function validateBodyWithContentType(
668	  contentType: string | undefined,
669	  body: Buffer,
670	  rule: BodyRule,
671	): BodyReport | null {
672	  const mediaType =
673	    typeof contentType === 'string' ? contentType.split(';', 1)[0].trim().toLowerCase() : '';
674	  if (mediaType !== 'application/json') {
675	    return parseFailure(
676	      typeof contentType === 'string'
677	        ? `媒体类型不符：期望 application/json（可带参数、忽略大小写），收到 "${contentType}"`
678	        : '缺少 Content-Type 头：期望 application/json（可带参数、忽略大小写）',
679	    );
680	  }
681	
682	  if (body.length === 0) {
683	    return parseFailure('请求正文为空，无法解析为 JSON');
684	  }
685	
686	  let text: string;
687	  try {
688	    text = new TextDecoder('utf-8', { fatal: true }).decode(body);
689	  } catch {
690	    return parseFailure('请求正文不是合法的 UTF-8 编码');
691	  }
692	
693	  let parsed: unknown;
694	  try {
695	    parsed = JSON.parse(text);
696	  } catch (e) {
697	    return parseFailure(`请求正文不是合法 JSON：${describeError(e)}`);
698	  }
699	
700	  const problems: StructureProblem[] = [];
701	  checkRule(rule, parsed, '', problems);
702	  if (problems.length > 0) {
703	    return {
704	      error: 'invalid_request_body',
705	      stage: 'structure',
706	      message: `请求正文与接口约定存在 ${problems.length} 处差异`,
707	      problems,
708	    };
709	  }
710	  return null;
711	}
