748	// ---------------------------------------------------------------------------
749	// 离线兼容报告（compare 子命令）
750	// ---------------------------------------------------------------------------
751	//
752	// 兼容方向固定为 旧 -> 新：旧配置能按“方法 + 字面路径”匹配且通过正文检查的
753	// 每一种请求，在新配置中仍须匹配并通过。只比较接口存在性与请求接受条件；
754	// 响应状态/头/正文/延迟与序列差异不影响结论。
755	//
756	// 双方都配置 requestBody 时，比较的是“规则所接受 JSON 值的集合包含关系”
757	// L(旧规则) ⊆ L(新规则)，而不是文本比较或抽样请求；每个不兼容点都附一份
758	// 具体反例（旧规则接受、新规则拒绝的完整 JSON 值）。
759	
760	interface ReportReason {
761	  // 正文差异：RFC 6901 指针（根为 ""）；接口级原因（如接口删除）无此字段
762	  readonly pointer?: string;
763	  readonly message: string;
764	}
765	
766	interface ReportExample {
767	  readonly method: HttpMethod;
768	  readonly path: string;
769	  readonly headers: { readonly [name: string]: string };
770	  readonly body: string;
771	}
772	
773	interface EndpointReport {
774	  readonly method: HttpMethod;
775	  readonly path: string;
776	  readonly compatible: boolean;
777	  readonly reasons: readonly ReportReason[];
778	  readonly example?: ReportExample;
779	}
780	
781	interface CompareReport {
782	  readonly compatible: boolean;
783	  readonly oldFile: string;
784	  readonly newFile: string;
785	  readonly endpoints: readonly EndpointReport[];
786	}
787	
788	interface BodyViolation {
789	  readonly pointer: string;
790	  readonly message: string;
791	  // 完整请求正文反例：被旧规则接受、被新规则拒绝
792	  readonly value: unknown;
793	}
794	
795	// 生成被规则接受的最小 JSON 值：object 只含必填字段，array 取空数组。
796	// 字段名可能是 "" 或 "__proto__"，一律用无原型对象按自有字段构造。
797	function sampleValue(rule: BodyRule): unknown {
798	  switch (rule.kind) {
799	    case 'string':
800	      return 'contractlab';
801	    case 'number':
802	    case 'integer':
803	      return 0;
804	    case 'boolean':
805	      return false;
806	    case 'null':
807	      return null;
808	    case 'array':
809	      return [];
810	    case 'object': {
811	      const obj: Record<string, unknown> = Object.create(null);
812	      for (const [name, field] of rule.fields) {
813	        if (field.required) {
814	          obj[name] = sampleValue(field.rule);
815	        }
816	      }
817	      return obj;
818	    }
819	  }
820	}
821	
822	// 在 object 规则的最小样本上补一个字段（字段值本身须被该字段规则接受）
823	function sampleObjectWith(
824	  rule: Extract<BodyRule, { kind: 'object' }>,
825	  name: string,
826	  value: unknown,
827	): Record<string, unknown> {
828	  const obj = sampleValue(rule) as Record<string, unknown>;
829	  obj[name] = value;
830	  return obj;
831	}
832	
833	// 生成被规则拒绝的 JSON 值（顶层类型即不符；任何规则都存在这样的值）
834	function violateValue(rule: BodyRule): unknown {
835	  switch (rule.kind) {
836	    case 'number':
837	      return 'contractlab'; // 非数字
838	    case 'integer':
839	      return 0.5; // 非整数
840	    default:
841	      return 0; // 非 string / boolean / null / object / array
842	  }
843	}
844	
845	function kindLabel(rule: BodyRule): string {
846	  if (rule.kind === 'object') {
847	    return rule.additionalProperties ? 'object（允许未声明字段）' : 'object（拒绝未声明字段）';
848	  }
849	  return rule.kind;
850	}
851	
852	// 选一个两个规则都未声明的字段名，用于构造“额外字段”反例
853	function freshFieldName(
854	  oldFields: ReadonlyMap<string, FieldRule>,
855	  newFields: ReadonlyMap<string, FieldRule>,
856	): string {
857	  for (let i = 0; ; i += 1) {
858	    const name = i === 0 ? 'extra' : `extra_${i}`;
859	    if (!oldFields.has(name) && !newFields.has(name)) {
860	      return name;
861	    }
862	  }
863	}
864	
865	// 递归判定 L(oldRule) ⊆ L(newRule)；把发现的每个反例（连同完整正文样本）推入 out。
866	// 不变式：value 必被 oldRule 接受、被 newRule 拒绝；pointer 用 RFC 6901 定位差异。
867	function collectViolations(
868	  oldRule: BodyRule,
869	  newRule: BodyRule,
870	  pointer: string,
871	  out: BodyViolation[],
872	): void {
873	  if (newRule.kind !== 'object' && newRule.kind !== 'array') {
874	    // 标量：仅同名兼容，外加 integer 放宽为 number；其余组合两集合相交为空或有差异
875	    const compatible =
876	      oldRule.kind === newRule.kind || (oldRule.kind === 'integer' && newRule.kind === 'number');
877	    if (!compatible) {
878	      // number -> integer 时样本必须是非整数，否则 0 会被新规则接受
879	      const value =
880	        oldRule.kind === 'number' && newRule.kind === 'integer' ? 0.5 : sampleValue(oldRule);
881	      out.push({
882	        pointer,
883	        value,
884	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 ${newRule.kind}`,
885	      });
886	    }
887	    return;
888	  }
889	
890	  if (newRule.kind === 'array') {
891	    if (oldRule.kind !== 'array') {
892	      out.push({
893	        pointer,
894	        value: sampleValue(oldRule),
895	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 array`,
896	      });
897	      return;
898	    }
899	    // 元素规则收紧：用非空数组 [反例] 体现（空数组双方都会接受）
900	    const sub: BodyViolation[] = [];
901	    collectViolations(oldRule.items, newRule.items, `${pointer}/0`, sub);
902	    for (const s of sub) {
903	      out.push({ pointer: s.pointer, message: s.message, value: [s.value] });
904	    }
905	    return;
906	  }
907	
908	  // newRule.kind === 'object'
909	  if (oldRule.kind !== 'object') {
910	    out.push({
911	      pointer,
912	      value: sampleValue(oldRule),
913	      message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 object`,
914	    });
915	    return;
916	  }
917	
918	  // (a) 新规则的必填字段必须被旧规则保证存在（旧规则未声明或仅可选即存在反例）
919	  for (const [name, newField] of newRule.fields) {
920	    if (!newField.required) {
921	      continue;
922	    }
923	    const oldField = oldRule.fields.get(name);
924	    if (!oldField || !oldField.required) {
925	      out.push({
926	        pointer: `${pointer}/${escapePointerSegment(name)}`,
927	        // 旧规则的最小样本不含可缺省/未声明字段，恰为反例
928	        value: sampleValue(oldRule),
929	        message: `新规则要求必填字段 ${JSON.stringify(name)}，旧规则允许缺省该字段`,
930	      });
931	    }
932	  }
933	
934	  // (b) 旧规则声明的字段，在新规则下仍须被接受
935	  for (const [name, oldField] of oldRule.fields) {
936	    const childPointer = `${pointer}/${escapePointerSegment(name)}`;
937	    const newField = newRule.fields.get(name);
938	    if (!newField) {
939	      if (!newRule.additionalProperties) {
940	        out.push({
941	          pointer: childPointer,
942	          value: sampleObjectWith(oldRule, name, sampleValue(oldField.rule)),
943	          message: `新规则拒绝旧规则允许的字段 ${JSON.stringify(name)}（新规则未声明且 additionalProperties 为 false）`,
944	        });
945	      }
946	      continue;
947	    }
948	    const sub: BodyViolation[] = [];
949	    collectViolations(oldField.rule, newField.rule, childPointer, sub);
950	    for (const s of sub) {
951	      out.push({
952	        pointer: s.pointer,
953	        message: s.message,
954	        value: sampleObjectWith(oldRule, name, s.value),
955	      });
956	    }
957	  }
958	
959	  // (c) 旧规则允许未声明的额外字段时，新规则必须同样放行这些字段
960	  if (oldRule.additionalProperties) {
961	    if (!newRule.additionalProperties) {
962	      const name = freshFieldName(oldRule.fields, newRule.fields);
963	      out.push({
964	        pointer: `${pointer}/${escapePointerSegment(name)}`,
965	        value: sampleObjectWith(oldRule, name, 0),
966	        message: '旧规则允许未声明的额外字段，新规则拒绝（additionalProperties 为 false）',
967	      });
968	    } else {
969	      // 新规则虽放行额外字段，但其新声明的字段会约束旧版原本自由的取值
970	      for (const [name, newField] of newRule.fields) {
971	        if (oldRule.fields.has(name)) {
972	          continue;
973	        }
974	        out.push({
975	          pointer: `${pointer}/${escapePointerSegment(name)}`,
976	          value: sampleObjectWith(oldRule, name, violateValue(newField.rule)),
977	          message: `旧规则对额外字段 ${JSON.stringify(name)} 不限制取值，新规则要求其为 ${kindLabel(newField.rule)}`,
978	        });
979	      }
980	    }
981	  }
982	}
983	
984	// 旧接口被旧配置接受的一个请求样本（用于“接口已删除”反例）
985	function acceptedRequestExample(endpoint: EndpointSpec): ReportExample {
986	  if (endpoint.bodyRule) {
987	    return {
988	      method: endpoint.method,
989	      path: endpoint.path,
990	      headers: { 'Content-Type': 'application/json' },
991	      body: JSON.stringify(sampleValue(endpoint.bodyRule)),
992	    };
993	  }
994	  return { method: endpoint.method, path: endpoint.path, headers: {}, body: '' };
995	}
996	
997	function compareEndpoint(oldEp: EndpointSpec, newEp: EndpointSpec | undefined): EndpointReport {
998	  const base = { method: oldEp.method, path: oldEp.path };
999	
1000	  if (!newEp) {
1001	    return {
1002	      ...base,
1003	      compatible: false,
1004	      reasons: [
