1076	async function runCompare(oldArg: string, newArg: string): Promise<never> {
1077	  const oldFile = path.resolve(oldArg);
1078	  const newFile = path.resolve(newArg);
1079	
1080	  const attempt = async (
1081	    file: string,
1082	  ): Promise<{ specs?: EndpointSpec[]; error?: string }> => {
1083	    try {
1084	      return { specs: await loadSpecsFromFile(file) };
1085	    } catch (e) {
1086	      return { error: describeError(e) };
1087	    }
1088	  };
1089	
1090	  // 两份文件都完整经历 读取 -> 解析 -> 严格校验；任一失败则不输出任何报告
1091	  const [oldResult, newResult] = await Promise.all([attempt(oldFile), attempt(newFile)]);
1092	  let failed = false;
1093	  if (oldResult.error !== undefined) {
1094	    process.stderr.write(`${APP_NAME}: compare 旧文件：${oldResult.error}\n`);
1095	    failed = true;
1096	  }
1097	  if (newResult.error !== undefined) {
1098	    process.stderr.write(`${APP_NAME}: compare 新文件：${newResult.error}\n`);
1099	    failed = true;
1100	  }
1101	  if (failed) {
1102	    process.exit(2);
1103	  }
1104	
1105	  const report = compareConfigs(
1106	    oldResult.specs as EndpointSpec[],
1107	    newResult.specs as EndpointSpec[],
1108	    oldFile,
1109	    newFile,
1110	  );
1111	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
1112	  process.exit(report.compatible ? 0 : 1);
1113	}
