1220	// JSON Pointer 段反转义：~1 -> /，~0 -> ~；其余 “~” 用法非法
1221	function unescapeRefSegment(
1222	  segment: string,
1223	  ref: string,
1224	  ctx: ImportCtx,
1225	  where: string,
1226	): string {
1227	  let out = '';
1228	  for (let i = 0; i < segment.length; i += 1) {
1229	    const ch = segment[i];
1230	    if (ch === '~') {
1231	      const next = segment[i + 1];
1232	      if (next === '0') {
1233	        out += '~';
1234	        i += 1;
1235	      } else if (next === '1') {
1236	        out += '/';
1237	        i += 1;
1238	      } else {
1239	        importFail(ctx, where, `$ref "${ref}" 含非法的 "~" 转义（仅支持 ~0 与 ~1）`);
1240	      }
1241	    } else {
1242	      out += ch;
1243	    }
1244	  }
1245	  return out;
1246	}
