1536	  const names: string[] = [];
1537	  const seen = new Set<string>();
1538	  for (const o of objs) {
1539	    for (const name of o.props.keys()) {
1540	      if (!seen.has(name)) {
1541	        seen.add(name);
1542	        names.push(name);
1543	      }
1544	    }
1545	  }
1546	
1547	  const props = new Map<string, NormRule>();
1548	  const required = new Set<string>();
1549	  // 非空但无法表达时的首个原因与位置（可能随后被收窄为空交集）
1550	  let inex: { reason: string; loc: string } | undefined;
1551	
1552	  const noteInexpressible = (reason: string, loc: string): void => {
1553	    if (inex === undefined) {
1554	      inex = { reason, loc };
1555	    }
1556	  };
1557	
1558	  for (const name of names) {
1559	    const isRequired = objs.some((o) => o.required.has(name));
1560	
1561	    // 真正约束该字段取值的声明分支（附精确来源位置）；以及首个禁止它出现的分支
1562	    // （未声明且该分支 additionalProperties 为 false）
1563	    const declarers: RuleBranch[] = [];
1564	    let forbiddener: RuleBranch | undefined;
1565	    for (let i = 0; i < flat.length; i += 1) {
1566	      const o = objs[i];
1567	      const sub = o.props.get(name);
1568	      if (sub !== undefined) {
1569	        declarers.push({ rule: sub, loc: `${flat[i].loc}.properties[${JSON.stringify(name)}]` });
1570	      } else if (!o.addl && forbiddener === undefined) {
1571	        forbiddener = flat[i];
1572	      }
1573	    }
1574	
1575	    if (forbiddener !== undefined) {
1576	      if (isRequired) {
1577	        return {
1578	          tag: 'empty',
1579	          reason:
1580	            `字段 ${JSON.stringify(name)} 在部分分支中为必填，但被另一分支禁止出现` +
1581	            '（未声明且 additionalProperties 为 false），交集为空',
1582	          loc: forbiddener.loc,
1583	        };
1584	      }
1585	      // 可选且被禁止：结果中不声明该字段即“禁止出现”。其余声明分支的取值交集
1586	      // 为何都无关紧要——该字段根本不能出现（声明分支中的非法 schema 仍在
1587	      // schemaToNorm 阶段被拒绝，不会走到这里）。
1588	      continue;
1589	    }
1590	
1591	    // 没有任何分支声明它：各分支仅以“允许额外字段”放行，交集对它无约束
1592	    if (declarers.length === 0) {
1593	      continue;
1594	    }
1595	
1596	    const sub = intersectRules(declarers, `${where}.properties[${JSON.stringify(name)}]`);
1597	
1598	    if (sub.tag === 'empty') {
1599	      if (isRequired) {
1600	        return {
1601	          tag: 'empty',
1602	          reason: `必填字段 ${JSON.stringify(name)} 的各分支规则交集为空：${sub.reason}`,
1603	          loc: sub.loc,
1604	        };
1605	      }
1606	      if (!addl) {
1607	        // 可选字段交集为空、结果又拒绝额外字段：不声明即“禁止出现”，可表达
1608	        continue;
1609	      }
1610	      // 所有分支都允许额外字段时，无法表达“仅该字段禁止出现、其他字段任意”
1611	      noteInexpressible(
1612	        `可选字段 ${JSON.stringify(name)} 的各分支规则交集为空（${sub.reason}），` +
1613	          '且所有分支都允许额外字段，现有规则种类无法表达“仅禁止该字段出现”',
