1621	      // 先记录原因；必填字段的不可表达在外层封闭也无法补救，最终仍会拒绝。
1622	      noteInexpressible(
1623	        `${isRequired ? '必填' : '可选'}字段 ${JSON.stringify(name)} 的各分支规则交集非空但无法表达：${sub.reason}`,
1624	        sub.loc,
1625	      );
1626	      props.set(name, sub.rule);
1627	      if (isRequired) {
1628	        required.add(name);
1629	      }
1630	      continue;
1631	    }
1632	
1633	    props.set(name, sub.rule);
1634	    if (isRequired) {
1635	      required.add(name);
1636	    }
1637	  }
1638	
1639	  const merged: NormObject = { kind: 'object', props, required, addl };
1640	  if (inex !== undefined) {
1641	    return { tag: 'inexpressible', rule: merged, reason: inex.reason, loc: inex.loc };
1642	  }
1643	  return { tag: 'nonempty', rule: merged };
1644	}
