1646	// 多个规则分支（标量/数组/对象）的交集，三态返回，结论与顺序、分组无关。
1647	function intersectRules(flat: readonly RuleBranch[], where: string): Intersection {
1648	  const first = flat[0].rule;
1649	  const isComposite = (k: NormRule['kind']): boolean => k === 'object' || k === 'array';
1650	
1651	  // 含对象/数组时，全部分支必须是同一种结构类型；对象/数组与标量、对象与数组
1652	  // 相交都为空。纯标量分支（如 number 与 integer）不在此拒绝，交给下方的
1653	  // 标量交集处理（number ∩ integer 取 integer，并非为空）。
1654	  if (isComposite(first.kind)) {
1655	    for (let i = 1; i < flat.length; i += 1) {
1656	      if (flat[i].rule.kind !== first.kind) {
1657	        return {
1658	          tag: 'empty',
1659	          reason: `类型 ${first.kind} 与 ${flat[i].rule.kind} 没有共同接受的值`,
1660	          loc: flat[i].loc,
1661	        };
1662	      }
1663	    }
1664	    if (first.kind === 'object') {
1665	      return intersectObjects(flat, where);
1666	    }
1667	
1668	    // first.kind === 'array'
1669	    // 数组只接受“每个元素都在元素交集内”的序列，空数组总被接受：
1670	    // - 元素交集可表达 -> 非空，items 取交集（空数组也接受）；
1671	    // - 元素交集为空 -> 真实交集仅含空数组，现有规则种类无法表达；
1672	    // - 元素交集非空但不可表达 -> 同样无法在不扩展规则种类的前提下表达。
1673	    const itemBranches: RuleBranch[] = flat.map((b) => ({
1674	      rule: (b.rule as Extract<NormRule, { kind: 'array' }>).items,
1675	      loc: `${b.loc}.items`,
1676	    }));
1677	    const itemRes = intersectRules(itemBranches, `${where}.items`);
1678	    if (itemRes.tag === 'empty') {
1679	      return {
1680	        tag: 'inexpressible',
1681	        rule: { kind: 'array', items: itemBranches[0].rule },
1682	        reason: `数组元素规则交集为空（${itemRes.reason}），交集仅含空数组，现有规则种类无法表达`,
1683	        loc: itemRes.loc,
1684	      };
1685	    }
1686	    if (itemRes.tag === 'inexpressible') {
1687	      return {
1688	        tag: 'inexpressible',
1689	        rule: { kind: 'array', items: itemRes.rule },
1690	        reason: `数组元素规则交集非空但无法表达：${itemRes.reason}`,
1691	        loc: itemRes.loc,
1692	      };
1693	    }
1694	    return { tag: 'nonempty', rule: { kind: 'array', items: itemRes.rule } };
1695	  }
1696	
1697	  // 全为标量（若混入对象/数组，首分支为标量而其后出现复合类型，交集为空）
1698	  for (let i = 1; i < flat.length; i += 1) {
1699	    if (isComposite(flat[i].rule.kind)) {
1700	      return {
1701	        tag: 'empty',
1702	        reason: `类型 ${first.kind} 与 ${flat[i].rule.kind} 没有共同接受的值`,
1703	        loc: flat[i].loc,
1704	      };
1705	    }
1706	  }
1707	
1708	  // 标量：顺序无关地求类型交集（number ∩ integer 取 integer）；遇空即整体为空
1709	  let acc: NormRule = first;
1710	  for (let i = 1; i < flat.length; i += 1) {
1711	    const hit = scalarIntersection(acc, flat[i].rule);
1712	    if (hit === null) {
1713	      return {
1714	        tag: 'empty',
1715	        reason: `类型 ${acc.kind} 与 ${flat[i].rule.kind} 没有共同接受的值`,
1716	        loc: flat[i].loc,
1717	      };
1718	    }
1719	    acc = hit;
1720	  }
1721	  return { tag: 'nonempty', rule: acc };
1722	}
