1724	// 规范化规则 -> 场景规则 JSON（object 显式写出 fields 与 additionalProperties；
1725	// 字段名可能是 ""/"__proto__"/含斜杠波浪号，一律用无原型对象按自有字段构造）
1726	function normToRuleJson(rule: NormRule): Record<string, unknown> {
1727	  switch (rule.kind) {
1728	    case 'object': {
1729	      const fields: Record<string, unknown> = Object.create(null);
1730	      for (const [name, sub] of rule.props) {
1731	        const subJson = normToRuleJson(sub);
1732	        fields[name] = rule.required.has(name) ? { ...subJson, required: true } : subJson;
1733	      }
1734	      return { type: 'object', fields, additionalProperties: rule.addl };
1735	    }
1736	    case 'array':
1737	      return { type: 'array', items: normToRuleJson(rule.items) };
1738	    default:
1739	      return { type: rule.kind };
1740	  }
