1743	// 转换一个操作的 requestBody；操作未声明 requestBody 时返回 undefined
1744	// （POST 移除接口旧规则；GET 本就不允许携带规则）。
1745	function importOperationBodyRule(
1746	  operation: Record<string, unknown>,
1747	  method: HttpMethod,
1748	  ctx: ImportCtx,
1749	  opWhere: string,
1750	): unknown {
1751	  if (!hasOwnKey(operation, 'requestBody')) {
1752	    return undefined;
1753	  }
1754	  const rbWhere = `${opWhere}.requestBody`;
1755	  if (method === 'GET') {
1756	    importFail(ctx, rbWhere, 'GET 操作不允许声明请求正文');
1757	  }
1758	  // requestBody 本身也可以是本文件内 $ref（可层层引用）
1759	  let node: unknown = operation.requestBody;
1760	  let nodeWhere = rbWhere;
1761	  let chain: readonly string[] = [];
1762	  for (;;) {
1763	    if (!isPlainObject(node)) {
1764	      importFail(ctx, nodeWhere, '必须是对象');
1765	    }
1766	    const ref = dereference(node, ctx, nodeWhere, chain);
1767	    if (!ref) {
1768	      break;
1769	    }
1770	    node = ref.target;
1771	    nodeWhere = ref.where;
1772	    chain = ref.refChain;
1773	  }
1774	  const rb = node as Record<string, unknown>;
1775	  for (const key of Object.keys(rb)) {
1776	    if (key !== 'required' && key !== 'content' && key !== 'description') {
1777	      importFail(ctx, nodeWhere, `含未支持的字段 "${key}"`);
1778	    }
1779	  }
1780	  if (rb.required !== true) {
1781	    importFail(
1782	      ctx,
1783	      `${nodeWhere}.required`,
1784	      `导入的请求正文约定一律按必填处理，required 必须为 true，收到 ${JSON.stringify(rb.required)}`,
1785	    );
1786	  }
1787	  const content = rb.content;
1788	  if (!isPlainObject(content)) {
1789	    importFail(ctx, `${nodeWhere}.content`, '必须是对象且仅含 "application/json" 一种媒体类型');
1790	  }
1791	  const mediaTypes = Object.keys(content as Record<string, unknown>);
1792	  if (mediaTypes.length !== 1 || mediaTypes[0] !== 'application/json') {
1793	    importFail(
1794	      ctx,
1795	      `${nodeWhere}.content`,
1796	      `仅允许且必须包含 "application/json" 一种媒体类型，收到 ${JSON.stringify(mediaTypes)}`,
1797	    );
1798	  }
1799	  const media = (content as Record<string, unknown>)['application/json'];
1800	  const mediaWhere = `${nodeWhere}.content["application/json"]`;
1801	  if (!isPlainObject(media)) {
1802	    importFail(ctx, mediaWhere, '必须是对象');
1803	  }
1804	  for (const key of Object.keys(media as Record<string, unknown>)) {
1805	    if (key !== 'schema' && key !== 'example' && key !== 'examples') {
1806	      importFail(ctx, mediaWhere, `含未支持的字段 "${key}"`);
1807	    }
1808	  }
1809	  if (!hasOwnKey(media as Record<string, unknown>, 'schema')) {
1810	    importFail(ctx, mediaWhere, '缺少 schema');
1811	  }
1812	  const norm = schemaToNorm(
1813	    (media as Record<string, unknown>).schema,
1814	    ctx,
1815	    `${mediaWhere}.schema`,
1816	    [],
1817	  );
1818	  return normToRuleJson(norm);
