1821	// 为场景每个接口选择文档操作并转换；任一失败抛 ImportError，不产生部分输出。
1822	// 未被选中的操作与不可达定义不参与转换。
1823	function importEndpoints(sceneRaw: unknown, ctx: ImportCtx): unknown[] {
1824	  const doc = ctx.doc;
1825	  if (!isPlainObject(doc)) {
1826	    importFail(ctx, '', '顶层必须是 JSON 对象');
1827	  }
1828	  const version = (doc as Record<string, unknown>).openapi;
1829	  if (typeof version !== 'string' || !/^3\.0\.\d+/.test(version)) {
1830	    importFail(ctx, 'openapi', `仅支持 OpenAPI 3.0.x，收到 ${JSON.stringify(version)}`);
1831	  }
1832	  const paths = (doc as Record<string, unknown>).paths;
1833	  if (!isPlainObject(paths)) {
1834	    importFail(ctx, 'paths', '必须是对象（路径 -> 路径项）');
1835	  }
1836	  const endpoints = (sceneRaw as { endpoints: unknown[] }).endpoints;
1837	  return endpoints.map((epRaw, index) => {
1838	    const ep = epRaw as { method: HttpMethod; path: string; responses: unknown };
1839	    const label = `场景接口 endpoints[${index}]（${ep.method} ${ep.path}）`;
1840	    if (!hasOwnKey(paths, ep.path)) {
1841	      importFail(ctx, 'paths', `${label} 缺少对应操作：路径 ${JSON.stringify(ep.path)} 不存在`);
1842	    }
1843	    const pathItem = (paths as Record<string, unknown>)[ep.path];
1844	    const pathWhere = `paths[${JSON.stringify(ep.path)}]`;
1845	    if (!isPlainObject(pathItem)) {
1846	      importFail(ctx, pathWhere, '必须是对象');
1847	    }
1848	    const methodKey = ep.method.toLowerCase();
1849	    if (!hasOwnKey(pathItem, methodKey)) {
1850	      importFail(ctx, pathWhere, `${label} 缺少对应操作：${methodKey} 操作不存在`);
1851	    }
1852	    const operation = (pathItem as Record<string, unknown>)[methodKey];
1853	    const opWhere = `${pathWhere}.${methodKey}`;
1854	    if (!isPlainObject(operation)) {
1855	      importFail(ctx, opWhere, '必须是对象');
1856	    }
1857	    const rule = importOperationBodyRule(operation, ep.method, ctx, opWhere);
1858	    // 仅替换 requestBody：保留接口顺序与 responses 原文
1859	    const out: { method: string; path: string; requestBody?: unknown; responses: unknown } = {
1860	      method: ep.method,
1861	      path: ep.path,
1862	      responses: ep.responses,
1863	    };
1864	    if (rule !== undefined) {
1865	      out.requestBody = rule;
1866	    }
1867	    return out;
1868	  });
1869	}
