2216	  // 两份输入都完整经历 读取 -> 解析 -> 严格校验；任一失败则不输出任何报告
2217	  const [snapResult, specResult] = await Promise.all([attemptSnapshot(), attemptSpecs()]);
2218	  let failed = false;
