2294	function validateReplayTarget(target: string, where: string): void {
2295	  if (target.length === 0 || !target.startsWith('/')) {
2296	    snapshotFail(where, `必须是以 "/" 开头的 HTTP 请求目标，收到 ${JSON.stringify(target)}`);
2297	  }
2298	  for (const ch of target) {
2299	    const code = ch.charCodeAt(0);
2300	    if (code <= 0x20 || code === 0x7f) {
2301	      snapshotFail(where, `含空白或控制字符，不是合法的 HTTP 请求目标：${JSON.stringify(target)}`);
2302	    }
2303	    if (code > 0xff) {
2304	      snapshotFail(where, `含 Latin-1 之外的字符，无法作为 HTTP 请求目标发送：${JSON.stringify(target)}`);
2305	    }
2306	  }
2307	}
