2309	// 过滤并校验待发送的业务头：剥离 Host/Expect/逐跳/分帧头（含 Connection
2310	// 指名的头），其余按原顺序、大小写与重复项保留；保留的头名称与值必须可发送。
2311	function filterReplayHeaders(
2312	  rawHeaders: readonly string[],
2313	  where: string,
2314	): [string, string][] {
2315	  const connectionNamed = new Set<string>();
2316	  for (let j = 0; j + 1 < rawHeaders.length; j += 2) {
2317	    if ((rawHeaders[j] as string).toLowerCase() === 'connection') {
2318	      for (const token of (rawHeaders[j + 1] as string).split(',')) {
2319	        const name = token.trim().toLowerCase();
2320	        if (name !== '') {
2321	          connectionNamed.add(name);
2322	        }
2323	      }
2324	    }
2325	  }
2326	  const out: [string, string][] = [];
2327	  for (let j = 0; j + 1 < rawHeaders.length; j += 2) {
2328	    const name = rawHeaders[j] as string;
2329	    const value = rawHeaders[j + 1] as string;
2330	    const lower = name.toLowerCase();
2331	    if (REPLAY_STRIP_HEADERS.has(lower) || connectionNamed.has(lower)) {
2332	      continue;
2333	    }
2334	    if (!HEADER_NAME_RE.test(name)) {
2335	      snapshotFail(`${where}[${j}]`, `不是可发送的 HTTP 头名称：${JSON.stringify(name)}`);
2336	    }
2337	    for (let k = 0; k < value.length; k += 1) {
2338	      const code = value.charCodeAt(k);
2339	      // 与响应头同一规则：允许水平制表符；拒绝换行及其余控制字符；仅 Latin-1
2340	      if ((code <= 0x1f && code !== 0x09) || code === 0x7f || code > 0xff) {
2341	        snapshotFail(
2342	          `${where}[${j + 1}]`,
2343	          `头 ${JSON.stringify(name)} 的值不得包含换行或其他控制字符，且只能使用 Latin-1 字符`,
2344	        );
2345	      }
2346	    }
2347	    out.push([name, value]);
2348	  }
2349	  return out;
2350	}
