2442	// 重放单条请求：独立连接、只尝试一次、不跟随重定向；总超时自开始连接覆盖
2443	// 完整收发，不因持续来数据而延长。通信失败时关闭连接并返回原因。
2444	function replayOne(port: number, request: ReplayRequest, timeoutMs: number): Promise<ReplayExchange> {
2445	  return new Promise((resolve) => {
2446	    let settled = false;
2447	    const done = (outcome: ReplayExchange): void => {
2448	      if (!settled) {
2449	        settled = true;
2450	        clearTimeout(timer);
2451	        resolve(outcome);
2452	      }
2453	    };
2454	
2455	    // 业务头在前（原顺序/大小写/重复项），随后按目标与实际字节数重建
2456	    // Host 与 Content-Length；每条请求独立连接，响应结束后关闭。
2457	    const headers: string[] = [];
2458	    for (const [name, value] of request.headers) {
2459	      headers.push(name, value);
2460	    }
2461	    headers.push('Host', `127.0.0.1:${port}`);
2462	    headers.push('Content-Length', String(request.body.byteLength));
2463	    headers.push('Connection', 'close');
2464	
2465	    const req = http.request({
2466	      host: '127.0.0.1',
2467	      port,
2468	      method: request.method,
2469	      path: request.target, // 原样发送：保留查询串与百分号编码，不归一化
2470	      headers,
2471	      agent: false, // 不连接池化：一次一条，每条只尝试一次
2472	    });
2473	
2474	    // 总超时：覆盖连接建立与完整收发，持续来数据不延长
2475	    const timer = setTimeout(() => {
2476	      req.destroy();
2477	      done({ ok: false, reason: `超过总超时 ${timeoutMs}ms（自开始连接覆盖完整收发）` });
2478	    }, timeoutMs);
2479	
2480	    req.on('response', (res) => {
2481	      const chunks: Buffer[] = [];
2482	      res.on('data', (chunk: Buffer) => chunks.push(chunk));
2483	      res.on('end', () => {
2484	        done({
2485	          ok: true,
2486	          response: { status: res.statusCode ?? 0, body: Buffer.concat(chunks) },
2487	        });
2488	      });
2489	      res.on('aborted', () => {
2490	        done({ ok: false, reason: '响应中途断开（部分响应不算完整）' });
2491	      });
2492	      res.on('error', (e: unknown) => {
2493	        done({ ok: false, reason: `响应读取失败：${describeError(e)}` });
2494	      });
2495	      res.on('close', () => {
2496	        if (!res.complete) {
2497	          done({ ok: false, reason: '响应中途断开（部分响应不算完整）' });
2498	        }
2499	      });
2500	    });
2501	    req.on('error', (e: Error) => {
2502	      done({ ok: false, reason: `通信失败：${e.message}` });
2503	    });
2504	    req.end(request.body);
2505	  });
2506	}
