2576	          body: { encoding: 'utf-8', content: request.plannedBody },
2577	        },
2578	        response: replayResponseJson(response),
2579	      });
2580	    }
2581	  }
2582	
2583	  const same = results.filter((r) => r.outcome === 'same').length;
2584	  const different = results.filter((r) => r.outcome === 'different').length;
2585	  const failed = results.filter((r) => r.outcome === 'failed').length;
2586	  const report: ReplayReport = {
2587	    requestsFile,
2588	    port,
2589	    timeoutMs,
2590	    total: results.length,
2591	    same,
2592	    different,
2593	    failed,
2594	    results,
2595	  };
2596	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
2597	  // 空快照或全部相同退出 0；存在差异或通信失败退出 1
2598	  process.exit(different === 0 && failed === 0 ? 0 : 1);
2599	}
