2620	function triggerReload(): Promise<ReloadResult> {
2621	  const job = reloadChain.then(async (): Promise<ReloadResult> => {
2622	    try {
2623	      // 校验通过前只构造局部变量，任何失败都不会触碰 activeState
2624	      const next = await loadStateFromFile(configFile, activeState.version + 1);
2625	      activeState = next; // 单次同步赋值：请求不可能看到混合配置
2626	      return { ok: true, version: activeState.version };
2627	    } catch (e) {
2628	      // 不修改配置/版本，不重置序列；旧场景的正常消费继续
2629	      return { ok: false, version: activeState.version, error: describeError(e) };
2630	    }
2631	  });
2632	  // 失败也不能打断后续 reload 的排队
2633	  reloadChain = job.then(
2634	    () => undefined,
2635	    () => undefined,
2636	  );
2637	  return job;
2638	}
