2640	function writeResponse(
2641	  res: http.ServerResponse,
2642	  status: number,
2643	  headers: { readonly [name: string]: string },
2644	  body: string,
2645	): void {
2646	  try {
2647	    res.writeHead(status, headers);
2648	    res.end(body === '' ? undefined : body);
2649	  } catch {
2650	    // 预留之后客户端可能已断开：响应仍计为已消费，发送失败仅静默忽略
2651	  }
2652	}
