2654	function versionHeaders(
2655	  version: number,
2656	  extra?: { readonly [name: string]: string },
2657	): { [name: string]: string } {
2658	  // 无原型对象：配置中名为 "__proto__" 的响应头在合并时不丢失
2659	  const headers: { [name: string]: string } = Object.create(null);
2660	  headers[VERSION_HEADER] = String(version);
2661	  if (extra) {
2662	    for (const [name, value] of Object.entries(extra)) {
2663	      headers[name] = value;
2664	    }
2665	  }
2666	  return headers;
2667	}
