2692	//
2693	// 业务/框架响应在“请求完整接收”那一刻就构造为一份计划快照：
2694	// 记录中保存的状态/应用层头/正文与随后真正写上线的字节共用同一份数据，
2695	// reload 不影响在途请求（它持有的是快照而非当前配置）。
2696	
2697	function freezeHeaders(headers: { [name: string]: string }): { readonly [name: string]: string } {
2698	  return Object.freeze(headers);
2699	}
2700	
2701	// 场景响应的应用层头：配置头 + 服务器填写的准确版本头（+ 必要时的默认 Content-Type）。
2702	// 不含 Content-Length/Connection/Date/Transfer-Encoding 等传输层自动头。
2703	function buildSceneHeaders(
2704	  item: ResponseSpec,
2705	  version: number,
2706	): { readonly [name: string]: string } {
2707	  const headers = versionHeaders(version);
2708	  let contentTypeSet = false;
2709	  for (const [name, value] of Object.entries(item.headers)) {
2710	    const lower = name.toLowerCase();
2711	    // 版本头由服务器填写且必须唯一准确：配置中的同名头（含大小写变体）可加载，发送时忽略其值
2712	    if (lower === VERSION_HEADER.toLowerCase()) {
2713	      continue;
2714	    }
2715	    if (lower === 'content-type') {
2716	      contentTypeSet = true;
2717	    }
2718	    headers[name] = value;
2719	  }
2720	  // 文本正文的默认内容类型；配置显式给出时不覆盖
2721	  if (!contentTypeSet && item.body !== '') {
2722	    headers['Content-Type'] = 'text/plain; charset=utf-8';
2723	  }
2724	  return freezeHeaders(headers);
2725	}
