2727	function buildScenePlanned(item: ResponseSpec, version: number): PlannedResponseSnapshot {
2728	  return {
2729	    kind: 'scene',
2730	    status: item.status,
2731	    headers: buildSceneHeaders(item, version),
2732	    body: item.body,
2733	  };
2734	}
