2737	  status: number,
2738	  version: number,
2739	  body: string,
2740	  contentType: string,
2741	): PlannedResponseSnapshot {
2742	  return {
2743	    kind: 'framework',
2744	    status,
2745	    headers: freezeHeaders(versionHeaders(version, { 'Content-Type': contentType })),
2746	    body,
