2750	// 按计划快照写出；writeHead/end 在已断开套接字上抛错时标记为中断（消费已成立）。
2751	function writePlanned(
2752	  res: http.ServerResponse,
2753	  planned: PlannedResponseSnapshot,
2754	  recordId: number,
2755	): void {
2756	  try {
2757	    res.writeHead(planned.status, { ...planned.headers });
2758	    res.end(planned.body === '' ? undefined : planned.body);
2759	  } catch {
2760	    requestLog.markDelivered(recordId, 'interrupted');
2761	  }
2762	}
