2764	// 挂载一次写出生命周期跟踪。每个被记录的请求恰好回复一次，故在接收完成后立即挂载：
2765	// 延迟期间断开也能标为中断；'sent' 为终态，随后连接正常关闭不回退。
2766	function attachDeliveryTracking(res: http.ServerResponse, recordId: number): void {
2767	  let settled = false;
2768	  const settle = (status: DeliveryStatus): void => {
2769	    if (settled) {
2770	      return;
2771	    }
2772	    settled = true;
2773	    requestLog.markDelivered(recordId, status);
2774	  };
2775	  res.once('finish', () => settle('sent'));
2776	  res.once('close', () => settle(res.writableFinished ? 'sent' : 'interrupted'));
2777	  res.once('error', () => settle('interrupted'));
2778	}
2779	
2780	// 延迟结束才按接收时的计划快照发送；即便客户端提前断开也继续计时（消费在预留时已成立）
2781	function schedulePlannedResponse(
2782	  res: http.ServerResponse,
2783	  planned: PlannedResponseSnapshot,
2784	  delay: number,
2785	  recordId: number,
2786	): void {
2787	  const timer = setTimeout(() => {
2788	    pendingTimers.delete(timer);
2789	    writePlanned(res, planned, recordId);
2790	  }, delay);
2791	  pendingTimers.add(timer);
2792	}
