2794	type BodyOutcome = 'received' | 'aborted' | 'too-large';
2795	
2796	interface ReceivedBody {
2797	  readonly outcome: BodyOutcome;
2798	  // 仅在 outcome 为 'received' 时有意义（完整请求体）
2799	  readonly body: Buffer;
2800	}
2801	
2802	// 完整接收请求体；未完整接收即断开返回 'aborted'（调用方不得推进序列）
2803	function receiveBody(req: http.IncomingMessage, res: http.ServerResponse): Promise<ReceivedBody> {
2804	  return new Promise((resolve) => {
2805	    let settled = false;
2806	    let size = 0;
2807	    const chunks: Buffer[] = [];
2808	    const finish = (outcome: BodyOutcome): void => {
2809	      if (!settled) {
2810	        settled = true;
2811	        resolve({ outcome, body: outcome === 'received' ? Buffer.concat(chunks) : Buffer.alloc(0) });
2812	      }
2813	    };
2814	    req.on('data', (chunk: Buffer) => {
2815	      size += chunk.byteLength;
2816	      if (size > MAX_BODY_BYTES) {
2817	        finish('too-large');
2818	        writeResponse(
2819	          res,
2820	          413,
2821	          versionHeaders(activeState.version, {
2822	            'Content-Type': 'text/plain; charset=utf-8',
2823	          }),
2824	          'payload too large\n',
2825	        );
2826	        // 等 413 刷出后再断开，避免客户端收不到响应
2827	        res.once('finish', () => req.socket.destroy());
2828	        return;
2829	      }
2830	      chunks.push(chunk);
2831	    });
2832	    req.on('end', () => finish('received'));
2833	    req.on('error', () => finish('aborted'));
2834	    req.on('aborted', () => finish('aborted'));
2835	    res.on('close', () => finish('aborted'));
2836	  });
2837	}
