2839	async function dispatch(
2840	  req: http.IncomingMessage,
2841	  res: http.ServerResponse,
2842	): Promise<void> {
2843	  res.on('error', () => {
2844	    // 写已销毁套接字等错误无需让进程崩溃
2845	  });
2846	
2847	  const method = String(req.method);
2848	  const target = String(req.url ?? '/'); // 含查询串的原始请求目标
2849	  const pathname = target.split('?')[0]; // 查询串不参与匹配
2850	
2851	  const { outcome, body } = await receiveBody(req, res);
2852	  if (outcome !== 'received') {
2853	    // aborted：未完整接收，不匹配、不预留、不推进任何序列，也不创建记录
2854	    // too-large：已回复 413，不创建记录、不消费序列
2855	    return;
2856	  }
2857	
2858	  // 管理范围：/__contractlab 本身及 /__contractlab/ 前缀。
2859	  // 其中所有请求都不记录、不消费业务序列（含未知子路径的 404）。
2860	  if (pathname === ADMIN_BASE || pathname.startsWith(ADMIN_PREFIX)) {
2861	    await handleAdmin(method, pathname, res);
2862	    return;
2863	  }
2864	
2865	  // 完整接收且不在管理范围：此刻创建记录并取得进程内递增编号。
2866	  // 编号只取决于完整接收顺序，与接口序列的消费位置互不相关。
2867	  const state = activeState;
2868	  const record = requestLog.create({
2869	    method,
2870	    target,
2871	    path: pathname,
2872	    rawHeaders: req.rawHeaders,
2873	    body,
2874	    configVersion: state.version,
2875	  });
2876	  attachDeliveryTracking(res, record.id);
2877	
2878	  // 业务匹配：在本次同步执行内抓取状态快照，预留后与后续 reload 互不影响
2879	  const endpoint =
2880	    method === 'GET' || method === 'POST'
2881	      ? state.endpoints.get(`${method} ${pathname}`)
2882	      : undefined;
2883	
2884	  if (!endpoint) {
2885	    // 未匹配请求：404，不消费、无消费位置
2886	    record.matched = false;
2887	    record.endpoint = `${method} ${pathname}`;
2888	    const planned = buildFrameworkPlanned(
2889	      404,
2890	      state.version,
2891	      'not found\n',
2892	      'text/plain; charset=utf-8',
2893	    );
2894	    record.plannedResponse = planned;
2895	    writePlanned(res, planned, record.id);
2896	    return;
2897	  }
2898	  record.matched = true;
2899	  record.endpoint = endpoint.key;
2900	
2901	  // 正文结构规则（如有）：校验失败返回 400 差异报告，不发送场景响应、不消费序列。
2902	  // 规则、序列与版本均取自上面同一快照 state。
2903	  if (endpoint.bodyRule) {
2904	    const report = validateBodyWithContentType(
2905	      req.headers['content-type'],
2906	      body,
2907	      endpoint.bodyRule,
2908	    );
2909	    if (report) {
2910	      record.bodyValidationPassed = false;
2911	      record.bodyRejection = report;
2912	      const planned = buildFrameworkPlanned(
2913	        400,
2914	        state.version,
2915	        `${JSON.stringify(report)}\n`,
2916	        'application/json; charset=utf-8',
2917	      );
2918	      record.plannedResponse = planned;
2919	      writePlanned(res, planned, record.id);
2920	      return;
2921	    }
2922	    record.bodyValidationPassed = true;
2923	  }
2924	
2925	  // 校验通过（或无规则）：立即预留，并把消费位置与场景计划响应记入同一条记录
2926	  const { position, item } = reserveNext(endpoint);
2927	  record.sequencePosition = position;
2928	  record.sequenceLength = endpoint.responses.length;
2929	  const planned = buildScenePlanned(item, state.version);
2930	  record.plannedResponse = planned;
2931	  schedulePlannedResponse(res, planned, item.delay, record.id);
2932	}
