3006	function shutdown(): void {
3007	  if (shuttingDown) {
3008	    return;
3009	  }
3010	  shuttingDown = true;
3011	  // 取消所有尚未发出的延迟响应
3012	  for (const timer of pendingTimers) {
3013	    clearTimeout(timer);
3014	  }
3015	  pendingTimers.clear();
3016	  // 关闭监听并断开空闲/在途连接，随后正常退出（退出码 0）
3017	  try {
3018	    server.closeAllConnections();
3019	  } catch {
3020	    // 旧版本兜底：忽略，下面的 close/超时仍会结束进程
3021	  }
3022	  server.close(() => process.exit(0));
3023	  setTimeout(() => process.exit(0), 2000).unref();
3024	}
