3026	async function startServer(configArg: string, port: number): Promise<void> {
3027	  configFile = path.resolve(configArg);
3028	
3029	  // 先读配置：配置无效时根本不会创建监听
3030	  activeState = await loadStateFromFile(configFile, 1);
3031	
3032	  server = http.createServer((req, res) => {
3033	    dispatch(req, res).catch(() => {
3034	      try {
3035	        req.socket.destroy();
3036	      } catch {
3037	        // 套接字可能已销毁
3038	      }
3039	    });
3040	  });
3041	
3042	  await new Promise<void>((resolve, reject) => {
3043	    server.once('error', reject);
3044	    // 仅监听本机回环地址
3045	    server.listen(port, '127.0.0.1', resolve);
3046	  });
3047	
3048	  const address = server.address();
3049	  const actualPort = typeof address === 'object' && address ? address.port : port;
3050	  process.stdout.write(
3051	    `${APP_NAME}: listening on http://127.0.0.1:${actualPort}\n` +
3052	      `${APP_NAME}: config ${configFile} (version 1, ${activeState.endpoints.size} endpoints)\n`,
3053	  );
3054	
3055	  const onSignal = (): void => shutdown();
3056	  process.on('SIGINT', onSignal);
3057	  process.on('SIGTERM', onSignal);
3058	}
