1	// 典型变更场景的回归测试 + 报告反例的真实重放
2	//
3	// 场景（每个都是一对真实场景配置文件 + 一次真实 compare 运行）：
4	// 不兼容组：
5	//   1. 双方都允许额外字段，但新版新增可选字段限制取值（additionalProperties 均为 true）
6	//   2. 必填字段嵌套收紧（嵌套对象内新增必填字段）
7	//   3. 删除带正文规则的 POST 接口
8	//   4. 启用正文规则（旧接口无 requestBody，新版启用）
9	//   5. 特殊字段名：空字段名、__proto__、含斜杠与波浪号的字段名
10	//      （断言原因中 JSON Pointer 的转义与定位，不断言自然语言措辞与原因排序）
11	// 兼容组：
12	//   6. 移除正文规则（更宽松）
13	//   7. 新增接口
14	//   8. 仅修改响应（状态/正文/延迟）
15	//
16	// 对每个不兼容接口：把报告给出的完整请求反例（方法、路径、请求头、原始正文）
17	// 原样发送到分别加载旧、新配置的真实本机服务（端口 0，实际监听地址）：
18	//   - 旧服务必须返回场景配置的可辨认成功响应（299 + contractlab-scene-success）；
19	//   - 新服务必须返回正文校验 400（且 stage 与变更相符）或接口不存在 404。
20	// 不使用独立解释器代替实际重放。
21	
22	import assert from 'node:assert/strict';
23	import test from 'node:test';
24	import {
25	  SCENE_BODY,
26	  SCENE_STATUS,
27	  makeTempDir,
28	  runCompare,
29	  sceneResponse,
30	  sendRequest,
31	  startServer,
32	  writeConfig,
33	  type RawRequest,
34	} from './helpers.ts';
35	
36	// 特殊字段名场景：字段表必须是无原型对象，否则 "__proto__" 键会被原型 setter 吞掉
37	function specialNameFields(required: boolean): Record<string, unknown> {
38	  const fields: Record<string, unknown> = Object.create(null);
39	  for (const name of ['', '__proto__', 'a/b', 'a~b']) {
40	    fields[name] = required ? { type: 'string', required: true } : { type: 'string' };
41	  }
42	  return fields;
43	}
44	
45	const OLD_CONFIG = {
46	  endpoints: [
47	    {
48	      // 场景 1：双方允许额外字段
49	      method: 'POST',
50	      path: '/scn/extra-field',
51	      requestBody: { type: 'object', additionalProperties: true },
52	      responses: [sceneResponse()],
53	    },
54	    {
55	      // 场景 2：嵌套必填对象
56	      method: 'POST',
57	      path: '/scn/nested-required',
58	      requestBody: {
59	        type: 'object',
60	        fields: {
61	          buyer: {
62	            type: 'object',
63	            required: true,
64	            fields: { name: { type: 'string', required: true } },
65	            additionalProperties: false,
66	          },
67	        },
68	        additionalProperties: false,
69	      },
70	      responses: [sceneResponse()],
71	    },
72	    {
73	      // 场景 3：将被删除的带正文规则 POST 接口
74	      method: 'POST',
75	      path: '/scn/deleted',
76	      requestBody: {
77	        type: 'object',
78	        fields: { id: { type: 'integer', required: true } },
79	        additionalProperties: false,
80	      },
81	      responses: [sceneResponse()],
82	    },
83	    {
84	      // 场景 4：旧版不校验正文
85	      method: 'POST',
86	      path: '/scn/enable-rule',
87	      responses: [sceneResponse()],
88	    },
89	    {
90	      // 场景 5：特殊字段名（全部可选）
91	      method: 'POST',
92	      path: '/scn/special-names',
93	      requestBody: {
94	        type: 'object',
95	        fields: specialNameFields(false),
96	        additionalProperties: false,
97	      },
98	      responses: [sceneResponse()],
99	    },
