  assert.equal(res.status, 400, `x 的非 null 值应拒绝：${res.body}`);
  res = await postJson(server.port, '/field-null', '{"other":1}');
  assert.equal(res.status, SCENE_STATUS, `额外字段仍放行：${res.body}`);
});
